; Title screen, F5 (COMPUTER / OPPONENT) option. Toggles bit 6 of the 20 characters of the option text on
; screen row 14 (columns 16-35), which switches each character between its normal and its inverted form,
; except character $4D. Then draws the end caps of the highlight box for the current value of
; option_yamo_player2: 0 boxes COMPUTER, 1 boxes OPPONENT. Called by show_title_screen and when F5 toggles
; the option. Changes A, X.
title_show_opponent_choice
        ldx #$13
title_opponent_toggle_loop
        lda game_screen+14*40+16,x
        cmp #$4d                        ; character $4D is not toggled
        beq title_opponent_toggle_next
        eor #$40                        ; bit 6: normal / inverted character
        sta game_screen+14*40+16,x
title_opponent_toggle_next
        dex
        bpl title_opponent_toggle_loop
        ldx #$50                        ; screen offset of row 14 from row 12 (2 rows of 40)
        lda option_yamo_player2
        jmp title_draw_option_box
; Title screen, F3 (1 PLAYER / 2 PLAYERS) option. Toggles bit 6 of the 20 characters of the option text on
; screen row 12 (columns 16-35), except character $4D, then draws the end caps of the highlight box for
; option_two_players: 0 boxes 1 PLAYER, 1 boxes 2 PLAYERS. Changes A, X.
