title_players_toggle_loop
        lda game_screen+12*40+16,x
        cmp #$4d
        beq title_players_toggle_next
        eor #$40
        sta game_screen+12*40+16,x
title_players_toggle_next
        dex
        bpl title_players_toggle_loop
        ldx #$00                        ; offset 0: row 12
        lda option_two_players
