        bne title_draw_option_box_second
        lda #$42                        ; left cap at column 15
        sta game_screen+12*40+15,x
        lda #$40
        sta game_screen+12*40+24,x
        lda #$56
        sta game_screen+12*40+26,x
        lda #$00
        sta game_screen+12*40+36,x
        rts
title_draw_option_box_second
